<?php
declare(strict_types=1);
require_once __DIR__ . '/conexao.php';
require_once __DIR__ . '/funcoes.php';
$totalProdutos = (int)$pdo->query('SELECT COUNT(*) FROM produtos')->fetchColumn();
$ativos = (int)$pdo->query("SELECT COUNT(*) FROM produtos WHERE status = 'Ativo'")->fetchColumn();
$estoqueBaixo = (int)$pdo->query('SELECT COUNT(*) FROM produtos WHERE estoque BETWEEN 1 AND 5')->fetchColumn();
$pedidos = (int)$pdo->query('SELECT COUNT(*) FROM pedidos')->fetchColumn();
$faturamento = (float)$pdo->query("SELECT COALESCE(SUM(total), 0) FROM pedidos WHERE status <> 'Cancelado'")->fetchColumn();
$ultimos = $pdo->query('SELECT id, cliente_nome, total, status, criado_em FROM pedidos ORDER BY id DESC LIMIT 5')->fetchAll();
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Dashboard | Aurora Tech</title><link rel="stylesheet" href="CSS/estilo.css"></head><body><header class="topo"><div class="container"><h1>Administração Aurora Tech</h1><nav><a href="index.php">Loja</a><a href="dashboard.php">Dashboard</a><a href="listar.php">Produtos</a><a href="pedidos.php">Pedidos</a></nav></div></header><main class="container pagina-interna"><p class="eyebrow">VISÃO GERAL</p><h1>Dashboard</h1><section class="metricas"><div class="metrica"><span>Produtos cadastrados</span><strong><?= $totalProdutos ?></strong><small>Catálogo total</small></div><div class="metrica"><span>Produtos ativos</span><strong><?= $ativos ?></strong><small>Disponíveis na loja</small></div><div class="metrica alerta-metrica"><span>Estoque baixo</span><strong><?= $estoqueBaixo ?></strong><small>Até 5 unidades</small></div><div class="metrica"><span>Pedidos</span><strong><?= $pedidos ?></strong><small>Total recebido</small></div><div class="metrica destaque-metrica"><span>Vendas demonstrativas</span><strong><?= formatarPreco($faturamento) ?></strong><small>Pedidos não cancelados</small></div></section><section class="dashboard-bloco"><div class="cabecalho"><div><h2>Pedidos recentes</h2><p>Últimas movimentações da loja.</p></div><a class="botao" href="pedidos.php">Ver todos</a></div><div class="tabela-wrapper"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Status</th><th>Data</th></tr></thead><tbody><?php if (!$ultimos): ?><tr><td colspan="5">Ainda não há pedidos.</td></tr><?php endif; ?><?php foreach ($ultimos as $pedido): ?><tr><td>#<?= (int)$pedido['id'] ?></td><td><?= e($pedido['cliente_nome']) ?></td><td><?= formatarPreco($pedido['total']) ?></td><td><span class="status <?= strtolower(e($pedido['status'])) ?>"><?= e($pedido['status']) ?></span></td><td><?= e(date('d/m/Y H:i', strtotime($pedido['criado_em']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="dashboard-bloco"><div class="cabecalho"><div><h2>Ações rápidas</h2><p>Atalhos para a rotina administrativa.</p></div></div><div class="acoes"><a class="botao" href="cadastro.php">Cadastrar produto</a><a class="botao secundario" href="listar.php">Gerenciar catálogo</a><a class="botao secundario" href="index.php">Abrir vitrine</a></div></section></main></body></html>
